},{"id":"nl-khoa-linh-thach","b":1,"mat":"khoa-linh-thach","n":2,"w":2.0},{"id":"nl-dao-van-thach","b":2,"mat":"dao-van-thach","n":1,"w":0.863636},{"id":"nl-manh-phap-bao","b":2,"mat":"manh-phap-bao","n":3,"w":0.863636},{"id":"cuoi-bach-loc","b":1,"mount":"bach-loc","gia":5000,"w":2.0},{"id":"cuoi-phong-lang","b":2,"mount":"phong-lang","gia":12000,"w":0.863636},{"id":"cuoi-tuyet-ly","b":2,"mount":"tuyet-ly","gia":15000,"w":0.863636},{"id":"cuoi-hoa-ky-lan","b":3,"mount":"hoa-ky-lan","gia":25000,"w":0.366667},{"id":"khoi-tieu-hoa","b":1,"comp":"tieu-hoa","gia":8000,"w":2.0},{"id":"khoi-ho-linh","b":1,"comp":"ho-linh","gia":8000,"w":2.0},{"id":"khoi-thanh-diep","b":2,"comp":"thanh-diep","gia":10000,"w":0.863636},{"id":"khoi-mac-anh","b":2,"comp":"mac-anh","gia":12000,"w":0.863636},{"id":"khoi-thach-sinh","b":3,"comp":"thach-sinh","gia":15000,"w":0.366667},{"id":"khoi-thiet-lan","b":3,"comp":"thiet-lan","gia":18000,"w":0.366667},{"id":"ao-hac-y","b":1,"outfit":"hac-y","gia":1500,"w":2.0}],"bh":{"hiem":10,"cuc":80},"loa":{"b":4,"ten":{"lt-1tr":"1 triệu Linh Thạch","lt-2tr":"2 triệu Linh Thạch","ngoc-7":"ngọc cấp 7","ngoc-8":"ngọc cấp 8","do-5":"trang bị phẩm Tiên","do-6":"trang bị Thượng Cổ"}},"qua_dau":300}'::jsonb where k = 'cfg';

do $$
declare
  v_gia jsonb := '{"thanh-sam":800,"hong-y":1500,"tien-nhan":10000,"hoang-kim":10000}';
  v_xoa jsonb := '["kim-bao","tu-bao","thien-kiem-bao","hoa-bao-xich-diem","phong-bao-hac-phong","kim-y-thien-kim","hu-khong-tu-y"]';
  v_only jsonb := '{"dong-phuc":"nam","bach-kiem-bao":"nam","tu-liem-y":"nu","thanh-sam":"nu","hong-y":"nu","huyet-giap":"nam","bi-ngo":"nam","tuyet-lanh":"nu","tien-nhan":"nu","hoang-kim":"nam","tet-do":"nam","thien-mach-bao":"nu","bang-y-han-bang":"nu"}';
  r record; v_look text; v_om jsonb; v_moi jsonb; v_k text; v_v jsonb; v_id text; v_g text; v_hoan bigint; v_doi boolean; v_mac text;
begin
  for r in select user_id, data from public.p2d_nhan_vat for update loop
    v_look := case when r.data ->> 'look' in ('nam', 'nu') then r.data ->> 'look' else 'nam' end;
    v_om := case when jsonb_typeof(r.data -> 'outfits') = 'object' then r.data -> 'outfits' else '{}'::jsonb end;
    v_moi := '{}'; v_hoan := 0; v_doi := false;
    for v_k, v_v in select e.key, e.value from jsonb_each(v_om) e loop
      v_id := split_part(v_k, ':', 1); v_g := coalesce(nullif(split_part(v_k, ':', 2), ''), v_look);
      if v_xoa ? v_id or (v_only ? v_id and v_only ->> v_id <> v_g) or v_id = 'thanh-sam' then
        v_doi := true; v_hoan := v_hoan + coalesce((v_gia ->> v_id)::bigint, 0);
      else v_moi := v_moi || jsonb_build_object(v_k, v_v);
      end if;
    end loop;
    v_mac := r.data ->> 'outfit';
    if v_mac is not null and (v_xoa ? v_mac or (v_only ? v_mac and v_only ->> v_mac <> v_look)) then v_doi := true; else v_mac := null; end if;
    continue when not v_doi;
    update public.p2d_nhan_vat
      set data = case when v_mac is not null then jsonb_set(r.data, '{outfits}', v_moi) - 'outfit' else jsonb_set(r.data, '{outfits}', v_moi) end,
          phien_ban = phien_ban + 1, updated_at = now()
      where user_id = r.user_id;
    if v_hoan > 0 then
      insert into public.p2d_hom_thu (user_id, noi_dung, ly_do)
      values (r.user_id, jsonb_build_object('coins', v_hoan, 'tieu_de', 'Hoàn Linh Thạch trang phục đã gỡ'), 'hoan_thoi_trang');
    end if;
  end loop;
end;
$$;
